package com.bank.text;

import java.util.concurrent.*;
import java.util.logging.*;

public class BuilderChoiceDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        // String: fixed, immutable, shared.
        final String accountId = "SAV2001";

        // StringBuilder: single-threaded fast building.
        StatementBuilder sb = new StatementBuilder();
        String statement = sb.build(accountId, 5);
        log.info(() -> "Statement:\n" + statement);

        // StringBuffer: multiple threads append safely to ONE buffer.
        AuditBuffer audit = new AuditBuffer();
        ExecutorService pool = Executors.newFixedThreadPool(4);
        CountDownLatch latch = new CountDownLatch(4);
        for (int t = 0; t < 4; t++) {
            final int id = t;
            pool.submit(() -> {
                for (int i = 0; i < 100; i++) audit.record("worker" + id + "-txn" + i);
                latch.countDown();
            });
        }
        latch.await();
        pool.shutdown();
        log.info(() -> "Audit lines recorded (no corruption) = " + audit.lineCount());
    }
}

