class StatementBuilder {
    // StringBuilder: NOT synchronized -> fast, for single-thread use.
    String build(String accountId, int lines) {
        StringBuilder sb = new StringBuilder(256);
        sb.append("National Bank of India - Statement for ").append(accountId).append("\n");
        for (int i = 0; i < lines; i++) {
            sb.append("Line ").append(i).append(": TXN amount 100\n");
        }
        return sb.toString();
    }
}

// ─── Would be AuditBuffer.java in a real project ───
class AuditBuffer {
    // StringBuffer: synchronized -> safe for concurrent append from many threads.
    private final StringBuffer buffer = new StringBuffer(4096);
    void record(String entry) {
        buffer.append(entry).append("\n"); // each append is atomic/synchronized
    }
    long lineCount() { return buffer.toString().lines().count(); }
}
